import sys

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.mod = 998244353

        def add(self, a, b):
            return (a + b) % self.mod

        def subtract(self, a, b):
            return (a - b) % self.mod

        def mult(self, a, b, inv_b=None):
            if inv_b is not None:
                return (a * inv_b) % self.mod
            return (a * b) % self.mod

        def smallInv(self, x):
            # Fermat's little theorem for modular inverse since mod is prime
            return pow(x, self.mod - 2, self.mod)

        def ncr(self, n, r):
            # Compute nCr modulo mod using Pascal's triangle or factorials
            if r > n or r < 0:
                return 0
            numerator = 1
            denominator = 1
            for i in range(r):
                numerator = (numerator * (n - i)) % self.mod
                denominator = (denominator * (i + 1)) % self.mod
            return (numerator * self.smallInv(denominator)) % self.mod

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])

    class HZSShufflesCards:
        def __init__(self):
            self.mod = NumberTheory.Mod998()

        def solve(self, n, m):
            phaseSize = 1
            p = 1
            i = 0
            while p != 0:
                p = self.mod.mult(p, n - i, self.mod.smallInv(n + m - i))
                phaseSize = self.mod.add(phaseSize, p)
                i += 1

            answer = 0
            for k in range(1, n + 1):
                numPhases = self.mod.mult(m + k, self.mod.smallInv(k))
                term = self.mod.mult(self.mod.ncr(n, k), numPhases, phaseSize)
                if k % 2 == 1:
                    answer = self.mod.add(answer, term)
                else:
                    answer = self.mod.subtract(answer, term)
            return answer

    solver = HZSShufflesCards()
    result = solver.solve(n, m)
    print(result)

if __name__ == "__main__":
    main()

